package com.bankpli.javabank.transfer;import static org.junit.jupiter.api.Assertions.*;import java.math.BigDecimal;import java.time.LocalDate;import org.junit.jupiter.api.Test;
class TransferServicesTest{private final TransferValidator v=new TransferValidator();private TransferRequest r(BigDecimal amount,Priority p,TransferType t,LocalDate date){return new TransferRequest("1","100001","2","100001",amount,p,t,date,true,true);}@Test void documentedValidationBoundaries(){LocalDate now=LocalDate.now();assertTrue(v.validate(r(BigDecimal.ZERO,Priority.STANDARD,TransferType.INTERNAL,now),now,true).isPresent());assertTrue(v.validate(r(new BigDecimal("-50"),Priority.STANDARD,TransferType.INTERNAL,now),now,true).isPresent());assertTrue(v.validate(r(new BigDecimal("100"),Priority.STANDARD,TransferType.INTERNAL,now.plusDays(10)),now,true).isEmpty());assertTrue(v.validate(r(new BigDecimal("15000000"),Priority.STANDARD,TransferType.INTERNAL,now),now,true).isPresent());assertTrue(v.validate(r(new BigDecimal("15000000"),Priority.URGENT,TransferType.INTERNAL,now),now,true).isEmpty());assertTrue(v.validate(r(BigDecimal.ONE,Priority.STANDARD,TransferType.INTERNAL,now.minusDays(1)),now,true).isPresent());assertTrue(v.validate(r(BigDecimal.ONE,Priority.STANDARD,TransferType.INTERNAL,now.plusDays(366)),now,true).isPresent());assertTrue(v.validate(r(BigDecimal.ONE,Priority.STANDARD,TransferType.INTERNAL,now.plusDays(365)),now,true).isEmpty());}@Test void feeMatchesPliTiers(){FeeCalculator f=new FeeCalculator();assertEquals(new BigDecimal("16.25"),f.calculate(new BigDecimal("1000"),Priority.HIGH,TransferType.EXTERNAL));assertEquals(new BigDecimal("40.00"),f.calculate(new BigDecimal("1000"),Priority.URGENT,TransferType.WIRE));}}
